"use strict";(globalThis.webpackChunkopnsense_documentation||=[]).push([[998],{9415(e){e.exports=JSON.parse('{"version":{"pluginId":"default","version":"current","label":"Next","banner":null,"badge":false,"noIndex":false,"className":"docs-version-current","isLast":true,"docsSidebars":{"chapters":[{"type":"link","href":"/TW4TECH-Documentation-Deliverables/docs/preface","label":"Preface","docId":"preface","unlisted":false},{"type":"link","href":"/TW4TECH-Documentation-Deliverables/docs/the-machine","label":"The machine","docId":"the-machine","unlisted":false},{"type":"link","href":"/TW4TECH-Documentation-Deliverables/docs/sign-in","label":"Sign in","docId":"sign-in","unlisted":false},{"type":"link","href":"/TW4TECH-Documentation-Deliverables/docs/the-room","label":"The room","docId":"the-room","unlisted":false},{"type":"link","href":"/TW4TECH-Documentation-Deliverables/docs/a-script","label":"A script","docId":"a-script","unlisted":false},{"type":"link","href":"/TW4TECH-Documentation-Deliverables/docs/the-calls","label":"The calls","docId":"the-calls","unlisted":false},{"type":"link","href":"/TW4TECH-Documentation-Deliverables/docs/keep-writing","label":"Keep writing","docId":"keep-writing","unlisted":false}]},"docs":{"a-script":{"id":"a-script","title":"A script","description":"The box is already the server. A script on your laptop opens HTTPS to the LAN address. The browser does a cousin of the same call when you press Save.","sidebar":"chapters"},"keep-writing":{"id":"keep-writing","title":"Keep writing","description":"Plugins extend the firewall. System \u2192 Firmware \u2192 Plugins is where they are installed. os-virtualbox is the lab example. This booklet does not ship a plugin. If you write one, follow the layout in opnsense/core and the development chapters on docs.opnsense.org. New API paths show up in the generated index after the plugin is really installed. Document the path only then.","sidebar":"chapters"},"preface":{"id":"preface","title":"Preface","description":"OPNsense is the firewall. This site is a booklet I keep open next to the official handbook. It is not a second copy of that handbook, and it is not the source tree at github.com/opnsense/core.","sidebar":"chapters"},"sign-in":{"id":"sign-in","title":"Sign in","description":"The live image and the installed system do not share one account. Mixing them up costs the first twenty minutes.","sidebar":"chapters"},"the-calls":{"id":"the-calls","title":"The calls","description":"Base URL on a fresh lab//192.168.1.1. JSON in both directions.","sidebar":"chapters"},"the-machine":{"id":"the-machine","title":"The machine","description":"OPNsense arrives as an image you boot, then as a system you install onto a disk. The download page is opnsense.org/download. Take amd64. dvd is the right file for a virtual machine. vga is the one you write to a USB stick when a monitor is attached.","sidebar":"chapters"},"the-room":{"id":"the-room","title":"The room","description":"After login, the GUI is a building. These are the rooms a first lab actually uses. The long tour is the official handbook.","sidebar":"chapters"}}}}')}}]);